reasons:
  design.clocks.clk_sys: "Use the Nexys A7-100T's 100 MHz CLK100MHZ board clock as the MMCM input."
  design.clocks.clk_pix: "Declare the required 74.25 MHz pixel clock as an MMCM-derived clock from the board's 100 MHz clock."
  design.resets.rst_pix: "Use CPU_RESETN as the FPGA reset source, synchronize its deassertion into the pixel-clock domain, and hold the pixel pipeline reset until the MMCM is locked."
  design.shell: "Run the shell in the pixel-clock domain so it can access the video modules' top-level register window without a separate clock-domain crossing."
  design.modules.video_source.window_base: "Place the pattern control at the first byte of the shell's module register region."
  design.modules.vga_output.window_base: "Place the frame counter at the next non-overlapping aligned register address."
  design.board_ports.CLK100MHZ: "The board's master XDC identifies CLK100MHZ as the board clock input."
  design.board_ports.CPU_RESETN: "Use the board reset input as the pixel-domain reset source; synchronize it for the derived clock domain."
  design.board_ports.UART_TXD_IN: "The board-pin direction note states UART_TXD_IN is an FPGA input."
  design.board_ports.UART_RXD_OUT: "The board-pin direction note states UART_RXD_OUT is an FPGA output."
