design:
  schema: fpga-design-agent/project/v1
  name: vmed
  board: nexys_a7_100t
  clocks:
    - {name: clk_sys, source: board, port: CLK100MHZ, mhz: 100}
    - {name: clk_pix, source: mmcm, from: clk_sys, mhz: 74.25}
  resets:
    - {name: rst_pix, domain: clk_pix, polarity: active_low, style: async, from: BTNC, via: reset_sync}
  shell: {design_id: VMED, clock: clk_pix, reset: rst_pix}
  modules:
    - name: video_source
      kind: rtl
      clocks: {clk: clk_pix}
      resets: {rst: rst_pix}
      window_base: 0
      register_crossings: {}
    - name: median_filter
      kind: rtl
      clocks: {clk: clk_pix}
      resets: {rst: rst_pix}
    - name: vga_output
      kind: rtl
      clocks: {clk: clk_pix}
      resets: {rst: rst_pix}
      window_base: 4
      register_crossings: {}
  connections:
    - {from: video_source.out, to: median_filter.in}
    - {from: median_filter.out, to: vga_output.in}
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: BTNC, dir: in, drive: input, to: video_source.button_center}
    - {name: BTNC, dir: in, drive: input, to: rst_pix}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: "VGA_R[3:0]", dir: out, drive: push-pull, from: vga_output.vga_r}
    - {name: "VGA_G[3:0]", dir: out, drive: push-pull, from: vga_output.vga_g}
    - {name: "VGA_B[3:0]", dir: out, drive: push-pull, from: vga_output.vga_b}
    - {name: VGA_HS, dir: out, drive: push-pull, from: vga_output.vga_hs}
    - {name: VGA_VS, dir: out, drive: push-pull, from: vga_output.vga_vs}
    - {name: "LED[0]", dir: out, drive: push-pull, from: clk_pix.locked}
  owned: []
  assumptions:
    - id: A-1
      text: The checkerboard pattern uses equal-sized black and white squares.
      default: Use a 16 by 16 active-pixel square size, anchored at the top-left of the active picture.
      reason: The specification requires a black-and-white checkerboard but does not specify its square size.
      affects: [video_source.pattern]
      status: open
    - id: A-2
      text: The test shell uses newline-terminated ASCII commands and responses.
      default: Use 8N1; accept PATTERN BARS, PATTERN CHECKER, and FRAME?; respond with OK or a decimal frame count, followed by a newline.
      reason: The UART framing and command syntax are not specified; this gives the host a simple way to select either pattern and read the counter.
      affects: [shell.design_id, video_source.contract.registers, vga_output.contract.registers]
      status: open
    - id: A-3
      text: BTNC is pressed
      default: Treat a high BTNC level as pressed.
      reason: The specification names the button but does not state its electrical polarity.
      affects: [video_source.contract.ports.button_center]
      status: open
    - id: A-4
      text: the pixel clock is not stable
      default: Hold the pixel-domain pipeline in reset and blank its outputs until the MMCM is locked; assert reset again if lock is lost.
      reason: The specification requires black output while the pixel clock is unstable but does not specify reset or lock sequencing.
      affects: [clk_pix, rst_pix, vga_output.contract.ports.vga_r, vga_output.contract.ports.vga_g, vga_output.contract.ports.vga_b]
      status: open

